// Degree-6 Horner polynomial, mod 2^16, FULL combinational mult-add chain
// (the long path -> lower Fmax; pipeline the stages to go faster).
module poly6_v13_8b (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    wire [15:0] t0 = y[15:0];
    wire [15:0] t1 = t0 * x[7:0] + 86;
    wire [15:0] t2 = t1 * x[7:0] + 73;
    wire [15:0] t3 = t2 * x[7:0] + 23;
    wire [15:0] t4 = t3 * x[7:0] + 69;
    wire [15:0] t5 = t4 * x[7:0] + 48;
    wire [15:0] t6 = t5 * x[7:0] + 52;
    wire [15:0] t7 = t6 * x[7:0] + 39;
    always @(posedge clk) begin
        if (!rst_n) y <= 16'd0;
        else        y <= t7;
    end
endmodule
